+            tvb, 4, 4, ENC_LITTLE_ENDIAN);
+    proto_tree_add_item(ubx_rxm_measx_tree, hf_ubx_rxm_measx_glotow,
+            tvb, 8, 4, ENC_LITTLE_ENDIAN);
