+        proto_tree_add_item(meas_tree, hf_ubx_rxm_measx_gnssid,
+                tvb, 44 + 24 * i, 1, ENC_NA);
+        proto_tree_add_item(meas_tree, hf_ubx_rxm_measx_svid,
