+                tvb, 48 + 24 * i, 4, ENC_LITTLE_ENDIAN);
+        proto_tree_add_item(meas_tree, hf_ubx_rxm_measx_dopplerhz,
+                tvb, 52 + 24 * i, 4, ENC_LITTLE_ENDIAN);
